mapper.update:
UPDATE ORDERS 
SET order_status = '주문취소' 
WHERE order_no = #{orderNo}
  AND member_no = #{memberNo}
  AND order_status IN ('주문접수', '결제완료')

mapper.select:
SELECT /* 1. 주문 공통 및 환불 정보 (ORDERS 테이블) */ o.order_no AS orderNo, o.member_no AS memberNo, o.delivery_fee AS deliveryFee, o.total_price AS totalPrice,
/* 2. 상세 상품 및 금액 정보 (ORDER_DETAIL 테이블) */ od.order_detail_no, od.order_qty AS quantity, od.price AS itemPrice,
/* 3. 상품명 (PRODUCT 테이블) */ p.product_name AS productName,
/* 4. 옵션 정보 (PRODUCT_OPTION 테이블) */ po.option1_type AS option1Type, po.option1_value AS option1Value, po.option2_type AS option2Type, po.option2_value AS option2Value, po.option3_type AS option3Type, po.option3_value AS option3Value
FROM ORDERS o JOIN ORDER_DETAIL od ON o.order_no = od.order_no JOIN PRODUCT p ON od.product_no = p.product_no LEFT JOIN PRODUCT_OPTION po ON od.option_id = po.option_id WHERE o.order_no = #{orderNo}
